use App\Services\Marketing\{MarketingStoryboardWorkspace,MarketingStoryboardUpload,MarketingStoryboardHandoff,MarketingProductionPreparation,MarketingStoryboardProduction,MarketingStoryboardBatchApproval,MarketingVideoFiles,MarketingVideoCompositor,MarketingEvolinkAdapter};
use Illuminate\Support\Facades\{Http,Queue};
use Illuminate\Support\Str;
use Illuminate\Http\UploadedFile;
class MarketingStoryboardBatchAcceptanceTest extends MarketingStoryboardTrialScopeTest {
 private function batch(bool $unknownUpload=false):array {
  $p=$this->researchProject();$doc=[];foreach([5,6,11,5] as $n=>$seconds)$doc[]=['visual'=>'Warehouse container shot '.($n+1),'duration'=>$seconds,'voiceover'=>'Approved spoken line '.($n+1),'subtitle'=>'Approved subtitle '.($n+1)];
  $r=MarketingRevision::create(['project_id'=>$p->id,'actor_id'=>$p->owner_id,'number'=>1,'document'=>['scenes'=>$doc],'context'=>[]]);$p->update(['current_revision_id'=>$r->id]);
  $s=app(MarketingStoryboardWorkspace::class)->initialize($p->id,$p->owner_id,(string)Str::uuid(),$p->version);$ref=app(MarketingStoryboardUpload::class)->store($p->id,$p->owner_id,UploadedFile::fake()->image('frame.png'),true);
  $w=Workspace::where('project_id',$p->id)->firstOrFail();$profile=$w->profile;$profile['voice']=['mode'=>'auto'];$w->update(['profile'=>$profile]);
  foreach($s['scenes'] as $i=>$scene){$old=MarketingSceneRevision::findOrFail($scene['revision_id']);$c=$old->content;$c['presenter_required']=false;$c['asset']=$ref;$c['readiness']='qa_passed';$c['director']['continuity']=str_repeat('Keep the warehouse and container unchanged. ',75);
   $pair=in_array($i,[1,2],true);$c['material_plan']=['mode'=>$pair?'first_last_frames':'single_image','roles'=>$pair?['start_frame','end_frame']:['start_frame'],'reason'=>'fixture'];
   foreach($c['material_plan']['roles'] as $role){$c['frames'][$role]['asset']=$ref;$c['frames'][$role]['readiness']='qa_passed';$c['frames'][$role]['required']=true;$c['frames'][$role]['person_presence']='absent';}
   $next=MarketingSceneRevision::create(['scene_id'=>$old->scene_id,'parent_id'=>$old->id,'content'=>$c,'signature'=>$old->signature]);MarketingScene::findOrFail($old->scene_id)->update(['current_revision_id'=>$next->id]);
  }
  $s=app(MarketingStoryboardWorkspace::class)->snapshot($p->id,$p->owner_id);app(MarketingStoryboardHandoff::class)->confirm($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version']);
  $scene=$s['scenes'][1];$input=$scene+['image'=>$ref,'opening_asset'=>$ref,'voice_asset'=>null,'payload'=>['model'=>'seedance-1.5-pro','quality'=>'720p','generate_audio'=>true],'configuration'=>['audio'=>['route'=>'native']]];
  $existing=MarketingVideoClip::create(['project_id'=>$p->id,'owner_id'=>$p->owner_id,'revision_id'=>$r->id,'request_id'=>(string)Str::uuid(),'scene_number'=>2,'fingerprint'=>hash('sha256','saved-second-clip'),'status'=>'completed','expires_at'=>now()->addDay(),'input'=>$input,'quote'=>[],'connection_fingerprint'=>'fixture','raw_path'=>'fixture/old-raw.mp4','raw_sha256'=>str_repeat('a',64),'output_path'=>'fixture/old-output.mp4','output_sha256'=>str_repeat('b',64)]);
  config(['marketing.native.api_key'=>'fixture']);
  $bounds=[];foreach($s['scenes'] as $i=>$scene)$bounds[$scene['scene_id']]=['digest'=>hash('sha256',json_encode($scene,JSON_THROW_ON_ERROR)),'video_cap_microusd'=>[300000,400000,650000,300000][$i],'reuse_clip'=>$i===1?$existing->id:null];
  config(['marketing.native.api_key'=>'fixture','marketing.storyboard.manual_testing_file'=>'missing-file','marketing.storyboard.economy_trial'=>[],'marketing.storyboard.batch_approval'=>['project'=>$p->id,'reference'=>'fake-batch-'.$p->id,'connection'=>app(MarketingEvolinkAdapter::class)->connectionFingerprint(),'story_version'=>$s['story_version'],'scenes'=>$bounds,'verified_at'=>'fixture','expires_at'=>now()->addHour()->toIso8601String(),'cap_microusd'=>1500000,'max_posts'=>10]]);
  AiConnection::updateOrCreate(['provider'=>'openai'],['enabled'=>true,'verified_at'=>now(),'api_key'=>'fixture','models'=>[['id'=>'gpt-5.6-luna']],'version'=>1]);
  $this->mock(MarketingVideoFiles::class)->shouldReceive('file')->andReturn('/fixture/file.mp4')->getMock()->shouldReceive('download')->andReturn(['path'=>'fixture/new-raw.mp4','sha256'=>str_repeat('c',64)]);
  $this->mock(MarketingVideoCompositor::class)->shouldReceive('storyboardClip')->andReturn(['path'=>'fixture/new-output.mp4','sha256'=>str_repeat('d',64),'editing_source'=>['path'=>'fixture/new-raw.mp4','sha256'=>str_repeat('c',64)]])->getMock()->shouldReceive('film')->andReturnUsing(function(){\Illuminate\Support\Facades\Storage::disk('local')->put('fixture/new-film.mp4','fake verified film');return ['path'=>'fixture/new-film.mp4','sha256'=>hash('sha256','fake verified film')];});
  $this->mock(\App\Services\AI\ProviderTransport::class)->shouldReceive('json')->andReturn(['id'=>'fake-prompt','status'=>'completed','usage'=>['input_tokens'=>1000,'output_tokens'=>100],'output'=>[['content'=>[['type'=>'output_text','text'=>'{"direction":"Keep the same warehouse and blue container. Follow the supplied timed director actions and match every required reference frame."}']]]]]);
  $credits=0;$videos=0;Http::fake(['https://api.evolink.ai/v1/models'=>Http::response(['data'=>[['id'=>'seedance-1.5-pro']]]),'https://api.evolink.ai/v1/credits'=>function()use(&$credits,$unknownUpload){$credits++;return Http::response(['data'=>['user'=>['remaining_credits'=>10000,'used_credits'=>10],'token'=>['remaining_credits'=>10000,'used_credits'=>$unknownUpload&&$credits>=3?11:10,'unlimited_credits'=>true]]]);},'https://files-api.evolink.ai/api/v1/files/upload/stream'=>Http::response(['success'=>true,'data'=>['file_id'=>'fake-upload','file_url'=>'https://files.evolink.ai/fake.png','expires_at'=>now()->addDay()->toIso8601String()]]),'https://api.evolink.ai/v1/videos/generations'=>function($q)use(&$videos){return Http::response(['id'=>'fake-video-'.$q['duration'].'-'.(++$videos),'usage'=>['credits_reserved'=>$q['duration']*3.5568]]);},'https://api.evolink.ai/v1/tasks/*'=>fn($q)=>Http::response(['id'=>basename($q->url()),'status'=>'completed','usage'=>['credits_used'=>(int)substr(basename($q->url()),11)*3.5568],'results'=>['https://files.evolink.ai/fake.mp4']])]);Queue::fake();return [$p,$s,$existing];
 }
 public function test_batch_reuses_second_clip_and_composes_27_seconds_with_ten_claims():void {
  [$p,$s,$existing]=$this->batch();$svc=app(MarketingStoryboardProduction::class);$plan=app(MarketingProductionPreparation::class)->prepareStoryboard($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version']);$this->assertEmpty($plan->manifest['blockers'],json_encode($plan->manifest['blockers'],JSON_UNESCAPED_UNICODE));$this->assertSame(1500000,$plan->manifest['budget']['cap_microusd']);$this->assertSame(10,$plan->manifest['budget']['total_posts']);$this->assertSame(3,$plan->manifest['budget']['video_requests']);$this->assertSame(4,$plan->manifest['budget']['upload_requests']);$this->assertSame(1,$plan->manifest['budget']['reused_clips']);
  $run=$svc->start($p->id,$p->owner_id,$s['story_version'],$plan->id,true);for($i=0;$i<35&&$run->fresh()->status!=='completed';$i++)$svc->advance($run->id);
  $this->assertSame('completed',$run->fresh()->status);$this->assertCount(4,$run->fresh()->result['clip_ids']);$this->assertSame($existing->id,$run->fresh()->result['clip_ids'][1]);$this->assertSame(4,MarketingVideoClip::where('project_id',$p->id)->count());$this->assertSame(10,Call::where('project_id',$p->id)->count());$this->assertSame(4,Call::where('project_id',$p->id)->where('role','upload')->where('actual_microusd',0)->count());
  $film=MarketingVideoFilm::where('project_id',$p->id)->firstOrFail();$this->assertSame('completed',$film->status);$this->assertSame(27,$film->input['duration']);$this->assertSame($existing->id,$film->input['scenes'][1]['clip_id']);$this->assertSame($run->id,$svc->start($p->id,$p->owner_id,$s['story_version'],$plan->id,true)->id);$svc->advance($run->id);$this->assertSame(1,MarketingVideoFilm::where('project_id',$p->id)->count());$this->assertSame(10,Call::where('project_id',$p->id)->count());
 }
 public function test_pause_records_specific_validation_failure_and_never_retries():void {
  [$p,$s]=$this->batch();$svc=app(MarketingStoryboardProduction::class);$plan=app(MarketingProductionPreparation::class)->prepareStoryboard($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version']);$run=$svc->start($p->id,$p->owner_id,$s['story_version'],$plan->id,true);
  $m=$plan->manifest;$m['configuration']['connection']='stale-worker-configuration';\App\Models\MarketingProductionPlan::whereKey($plan->id)->update(['manifest'=>json_encode($m)]);
  try{$svc->advance($run->id);$this->fail('Changed configuration must pause');}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){}
  $run->refresh();$this->assertSame('blocked',$run->status);$this->assertSame('validate_plan',$run->result['failure']['stage']);$this->assertStringContainsString('模型连接',$run->result['message']);$this->assertSame(409,$run->result['failure']['http_status']);$this->assertSame($run->result['message'],$svc->state($p->id,$p->owner_id,$run->id)['message']);\App\Models\MarketingProduction::whereKey($run->id)->update(['status'=>'completed','result'=>array_replace($run->result,['film_id'=>(string)Str::uuid()])]);$this->assertNull($svc->state($p->id,$p->owner_id,$run->id)['message']);\App\Models\MarketingProduction::whereKey($run->id)->update(['status'=>'blocked']);$this->assertNotEmpty($run->result['failure']['reference']);$this->assertSame(0,Call::where('project_id',$p->id)->count());
  $svc->advance($run->id);$this->assertSame(0,Call::where('project_id',$p->id)->count());Http::assertNotSent(fn($request)=>$request->method()==='POST');
 }
 public function test_unknown_upload_fee_keeps_link_and_never_submits_video_or_retries():void {
  [$p,$s]=$this->batch(true);$svc=app(MarketingStoryboardProduction::class);$plan=app(MarketingProductionPreparation::class)->prepareStoryboard($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version']);$run=$svc->start($p->id,$p->owner_id,$s['story_version'],$plan->id,true);
  try{for($i=0;$i<5;$i++)$svc->advance($run->id);$this->fail('unknown fee continued');}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){$this->assertSame(409,$e->getStatusCode());}
  $call=Call::where('project_id',$p->id)->where('role','upload')->firstOrFail();$this->assertSame('unknown',$call->status);$this->assertNotEmpty($call->result['file_url']);$this->assertSame(0,Call::where('project_id',$p->id)->where('role','video')->count());$count=Call::where('project_id',$p->id)->count();$svc->advance($run->id);$this->assertSame($count,Call::where('project_id',$p->id)->count());
 }
 public function test_changed_scene_is_not_covered_by_previous_batch_approval():void {
  [$p,$s]=$this->batch();$h=app(MarketingStoryboardHandoff::class)->build($p->id,$p->owner_id,$s['story_id']);$h['scene_map'][0]['seconds']=7;$this->assertFalse(app(MarketingStoryboardBatchApproval::class)->activate($h));Http::assertNothingSent();
 }
